import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), conc.TaskPanic> {
    scope {
        let t = task effect io {
            let s = conc.Semaphore(1)
            let _ = s.acquire()
            let _ = s.release()
            let _ = s.release()
            io.println("unreachable")
        }
        let _ = t.await()?
    }
    return Ok(())
}
